# Set Group ID (SGID) on Directories
# Ensures files created within inherit the directory's GID.

# 1. Shell Command (Symbolic)
chmod g+s /path/to/directory

# 2. Shell Command (Octal Notation)
# Example: 2 (SGID) + 770 (rwxrwx---)
chmod 2770 /path/to/directory

# Verification: Look for 's' in the group permissions
ls -ld /path/to/directory
# Output example: drwxrws--- (if group execution was set)

/* C/POSIX API Reference */
// Flag constant for SGID
#define SGID_FLAG 02000

// Set 0755 permissions + SGID
int result = chmod("/shared/data", 02755);

// Using macros (S_ISGID)
mode_t current = S_IRWXU | S_IRGRP | S_IXGRP;
chmod("/shared/data", current | S_ISGID);
